typedef long long int64;

typedef struct {
    int64 key;
    int pos;
    int rank;
} Record;

typedef struct {
    Record *records;
    int *roots;
    int64 *group_keys;
    int *group_starts;
    int groups;
    int n;
} Index;

static int *node_left, *node_right, *node_count;
static int node_used;
static int height_count;

static int new_node(int previous) {
    int current = ++node_used;
    node_left[current] = node_left[previous];
    node_right[current] = node_right[previous];
    node_count[current] = node_count[previous] + 1;
    return current;
}

static int insert_value(int previous, int lo, int hi, int value) {
    int current = new_node(previous);
    if (hi - lo == 1) return current;

    int mid = lo + (hi - lo) / 2;
    if (value < mid)
        node_left[current] = insert_value(node_left[previous], lo, mid, value);
    else
        node_right[current] = insert_value(node_right[previous], mid, hi, value);

    return current;
}

static int count_less(int root_r, int root_l, int lo, int hi, int cutoff) {
    if (cutoff <= lo) return 0;
    if (hi <= cutoff) return node_count[root_r] - node_count[root_l];

    int mid = lo + (hi - lo) / 2;
    if (cutoff <= mid)
        return count_less(node_left[root_r], node_left[root_l], lo, mid, cutoff);

    int left_count = node_count[node_left[root_r]] - node_count[node_left[root_l]];
    return left_count +
           count_less(node_right[root_r], node_right[root_l], mid, hi, cutoff);
}

static int compare_records(const void *a, const void *b) {
    const Record *x = (const Record *)a;
    const Record *y = (const Record *)b;
    if (x->key < y->key) return -1;
    if (x->key > y->key) return 1;
    return (x->pos > y->pos) - (x->pos < y->pos);
}

static void build_index(Index *idx, Record *records, int n) {
    idx->records = records;
    idx->n = n;
    idx->roots = (int *)malloc((size_t)n * sizeof(int));
    idx->group_keys = (int64 *)malloc((size_t)n * sizeof(int64));
    idx->group_starts = (int *)malloc((size_t)(n + 1) * sizeof(int));

    qsort(records, (size_t)n, sizeof(Record), compare_records);

    int groups = 0;
    for (int i = 0; i < n; ) {
        idx->group_keys[groups] = records[i].key;
        idx->group_starts[groups++] = i;
        int j = i + 1;
        while (j < n && records[j].key == records[i].key) j++;
        i = j;
    }
    idx->group_starts[groups] = n;
    idx->groups = groups;

    int group = 0;
    while (group < groups) {
        int start = idx->group_starts[group];
        int end = idx->group_starts[group + 1];
        int previous = 0;
        for (int i = start; i < end; i++) {
            previous = insert_value(previous, 0, height_count, records[i].rank);
            idx->roots[i] = previous;
        }
        group++;
    }
}

static int query_index(const Index *idx, int64 key, int left, int right,
                       int cutoff, int invert) {
    if (left > right) return 0;

    int lo = 0, hi = idx->groups;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (idx->group_keys[mid] < key) lo = mid + 1;
        else hi = mid;
    }
    if (lo == idx->groups || idx->group_keys[lo] != key) return 0;

    int start = idx->group_starts[lo];
    int end = idx->group_starts[lo + 1];

    int a = 0, b = end - start;
    while (a < b) {
        int mid = a + (b - a) / 2;
        if (idx->records[start + mid].pos < left) a = mid + 1;
        else b = mid;
    }
    int first = a;

    a = 0;
    b = end - start;
    while (a < b) {
        int mid = a + (b - a) / 2;
        if (idx->records[start + mid].pos <= right) a = mid + 1;
        else b = mid;
    }
    int after = a;
    if (first >= after) return 0;

    int root_r = idx->roots[start + after - 1];
    int root_l = first == 0 ? 0 : idx->roots[start + first - 1];
    int total = node_count[root_r] - node_count[root_l];

    int less;
    if (cutoff <= 0) less = 0;
    else if (cutoff >= height_count) less = total;
    else less = count_less(root_r, root_l, 0, height_count, cutoff);

    return invert ? total - less : less;
}

